	<!-- ECH\xD7\u6307\u7EB9\u51B2\u7A81\u5F39\u7A97 -->
	<div class="modal-overlay" id="echConflictModal" onclick="closeECHConflictModal(event)">
		<div class="modal ech-conflict-modal" onclick="event.stopPropagation()">
			<button type="button" class="modal-close" onclick="closeECHConflictModal()">\xD7</button>
			<div class="ech-header">
				<div class="ech-icon">\u26A0\uFE0F</div>
				<h2 class="ech-title">ECH \u4E0E\u6D4F\u89C8\u5668\u6307\u7EB9\u51B2\u7A81</h2>
			</div>
			<div class="ech-content" style="text-align: left;">
				<p class="ech-text">\u60A8\u5DF2\u5F00\u542F ECH\uFF0C\u4F46\u5F53\u524D\u9009\u62E9\u7684\u6D4F\u89C8\u5668\u6307\u7EB9\u300C<span id="echConflictFingerprint"></span>\u300D\u4E0D\u652F\u6301 ECH\u3002</p>
				<p class="ech-text">ECH\uFF08Encrypted ClientHello\uFF09\u4EC5\u5728 <strong>chrome / firefox</strong>
					\u6307\u7EB9\u4E0B\u751F\u6548\u3002\u8BF7\u9009\u62E9\u5904\u7406\u65B9\u5F0F\uFF1A\u5207\u6362\u5230\u652F\u6301\u7684\u6D4F\u89C8\u5668\u6307\u7EB9\u4EE5\u4FDD\u7559 ECH\uFF0C\u6216\u5173\u95ED ECH\u3002</p>
			</div>
			<div class="ech-buttons">
				<button type="button" class="btn btn-ech-option btn-ech-chrome"
					onclick="resolveECHConflict('chrome')">\u4F7F\u7528 chrome \u6307\u7EB9\u5E76\u5F00\u542F ECH</button>
				<button type="button" class="btn btn-ech-option btn-ech-firefox"
					onclick="resolveECHConflict('firefox')">\u4F7F\u7528 firefox \u6307\u7EB9\u5E76\u5F00\u542F ECH</button>
				<button type="button" class="btn btn-ech-option btn-ech-disable"
					onclick="resolveECHConflict('disable')">\u5173\u95ED ECH</button>
			</div>
		</div>
	</div>

